modules.moduleCss:
.blog-header {
  padding: 80px 24px 48px;
  text-align: center;
}

.blog-header__inner {
  max-width: 720px;
  margin: 0 auto;
}

.blog-header__title {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 800;
  color: var(--color-text);
  margin: 0 0 12px;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.blog-header__tagline {
  font-family: var(--font-body);
  font-size: 1.15rem;
  color: var(--color-text-muted);
  margin: 0;
  line-height: 1.6;
}

@media (max-width: 768px) {
  .blog-header {
    padding: 48px 20px 32px;
  }
  .blog-header__title {
    font-size: 2.2rem;
  }
}

.topic-filter {
  padding: 0 24px 48px;
  text-align: center;
}

.topic-filter__inner {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

.topic-filter__pill {
  display: inline-block;
  padding: 8px 20px;
  font-family: var(--font-body);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-text-muted);
  text-decoration: none;
  border: 1px solid var(--color-border, rgba(0,0,0,0.1));
  border-radius: 100px;
  transition: all 0.2s ease;
}

.topic-filter__pill:hover {
  color: var(--color-text);
  border-color: var(--color-text);
}

.topic-filter__pill--active {
  background: var(--color-text);
  color: var(--color-bg);
  border-color: var(--color-text);
}

@media (max-width: 768px) {
  .topic-filter {
    padding: 0 16px 32px;
  }
  .topic-filter__pill {
    font-size: 0.85rem;
    padding: 6px 16px;
  }
}

.post-grid {
  padding: 0 24px 80px;
}

.post-grid__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.post-card {
  background: var(--color-surface, #ffffff);
  border: 1px solid var(--color-border, rgba(0,0,0,0.08));
  border-radius: 12px;
  overflow: hidden;
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.post-card:hover {
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
  transform: translateY(-2px);
}

.post-card__image-link {
  display: block;
  aspect-ratio: 16 / 10;
  overflow: hidden;
}

.post-card__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.post-card:hover .post-card__image {
  transform: scale(1.03);
}

.post-card__body {
  padding: 20px 24px 24px;
}

.post-card__meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 10px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

.post-card__date {
  white-space: nowrap;
}

.post-card__author::before {
  content: '\00B7';
  margin-right: 12px;
}

.post-card__title {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 700;
  line-height: 1.3;
  margin: 0 0 8px;
}

.post-card__title a {
  color: var(--color-text);
  text-decoration: none;
}

.post-card__title a:hover {
  color: var(--color-accent);
}

.post-card__excerpt {
  font-family: var(--font-body);
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin: 0 0 12px;
}

.post-card__tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.post-card__tag {
  font-family: var(--font-body);
  font-size: 0.78rem;
  color: var(--color-accent);
  text-decoration: none;
  padding: 3px 10px;
  border: 1px solid currentColor;
  border-radius: 100px;
  transition: background 0.15s ease;
}

.post-card__tag:hover {
  background: var(--color-accent);
  color: #ffffff;
}

.post-grid__pagination {
  max-width: 1200px;
  margin: 48px auto 0;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 24px;
  font-family: var(--font-body);
  font-size: 0.95rem;
}

.post-grid__page-link {
  color: var(--color-accent);
  text-decoration: none;
  font-weight: 600;
}

.post-grid__page-link:hover {
  text-decoration: underline;
}

.post-grid__page-info {
  color: var(--color-text-muted);
}

@media (max-width: 1024px) {
  .post-grid__inner {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .post-grid {
    padding: 0 16px 48px;
  }
  .post-grid__inner {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

.post-header {
  padding: 80px 24px 0;
}

.post-header__inner {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.post-header__meta {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 20px;
}

.post-header__tag {
  font-family: var(--font-body);
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--color-accent);
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.post-header__tag:hover {
  text-decoration: underline;
}

.post-header__title {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 800;
  color: var(--color-text);
  line-height: 1.15;
  margin: 0 0 20px;
  letter-spacing: -0.02em;
}

.post-header__excerpt {
  font-family: var(--font-body);
  font-size: 1.2rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin: 0 0 28px;
}

.post-header__byline {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 40px;
}

.post-header__avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  object-fit: cover;
}

.post-header__byline-text {
  text-align: left;
}

.post-header__author {
  display: block;
  font-family: var(--font-body);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text);
}

.post-header__date {
  font-family: var(--font-body);
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

.post-header__image-wrap {
  max-width: 960px;
  margin: 0 auto;
}

.post-header__image {
  width: 100%;
  height: auto;
  border-radius: 12px;
  display: block;
}

@media (max-width: 768px) {
  .post-header {
    padding: 48px 20px 0;
  }
  .post-header__title {
    font-size: 2rem;
  }
  .post-header__excerpt {
    font-size: 1.05rem;
  }
}

.post-body {
  padding: 48px 24px;
}

.post-body__content {
  max-width: 720px;
  margin: 0 auto;
  font-family: var(--font-body);
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--color-text);
}

.post-body__content h2 {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  margin: 2.5rem 0 1rem;
  color: var(--color-text);
  letter-spacing: -0.01em;
}

.post-body__content h3 {
  font-family: var(--font-heading);
  font-size: 1.35rem;
  font-weight: 600;
  margin: 2rem 0 0.75rem;
  color: var(--color-text);
}

.post-body__content p {
  margin: 0 0 1.5em;
}

.post-body__content a {
  color: var(--color-accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.post-body__content a:hover {
  text-decoration: none;
}

.post-body__content img {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
  margin: 2rem 0;
}

.post-body__content blockquote {
  border-left: 3px solid var(--color-accent);
  margin: 2rem 0;
  padding: 0.5rem 0 0.5rem 1.5rem;
  font-style: italic;
  color: var(--color-text-muted);
}

.post-body__content ul,
.post-body__content ol {
  margin: 0 0 1.5em;
  padding-left: 1.5em;
}

.post-body__content li {
  margin-bottom: 0.5em;
}

.post-body__content pre {
  background: var(--color-surface, #f5f5f5);
  border-radius: 8px;
  padding: 1.25rem;
  overflow-x: auto;
  margin: 2rem 0;
  font-size: 0.9rem;
  line-height: 1.5;
}

.post-body__content code {
  font-size: 0.9em;
  background: var(--color-surface, #f5f5f5);
  padding: 2px 6px;
  border-radius: 4px;
}

.post-body__content pre code {
  background: none;
  padding: 0;
}

@media (max-width: 768px) {
  .post-body {
    padding: 32px 20px;
  }
  .post-body__content {
    font-size: 1.05rem;
  }
}

.author-bio {
  padding: 0 24px 48px;
}

.author-bio__inner {
  max-width: 720px;
  margin: 0 auto;
  border-top: 1px solid var(--color-border, rgba(0,0,0,0.08));
  padding-top: 40px;
}

.author-bio__heading {
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-text-muted);
  margin: 0 0 20px;
}

.author-bio__card {
  display: flex;
  gap: 20px;
  align-items: flex-start;
}

.author-bio__avatar {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.author-bio__name {
  display: block;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-text);
  margin-bottom: 6px;
}

.author-bio__text {
  font-family: var(--font-body);
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin: 0;
}

@media (max-width: 640px) {
  .author-bio__card {
    flex-direction: column;
    align-items: center;
    text-align: center;
  }
}

.related-posts {
  padding: 48px 24px 80px;
  background: var(--color-surface, #fafafa);
}

.related-posts__inner {
  max-width: 1080px;
  margin: 0 auto;
}

.related-posts__heading {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 32px;
  text-align: center;
}

.related-posts__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

.related-posts__card {
  background: var(--color-bg, #ffffff);
  border: 1px solid var(--color-border, rgba(0,0,0,0.08));
  border-radius: 10px;
  overflow: hidden;
  transition: box-shadow 0.2s ease;
}

.related-posts__card:hover {
  box-shadow: 0 6px 20px rgba(0,0,0,0.06);
}

.related-posts__image-link {
  display: block;
  aspect-ratio: 16 / 10;
  overflow: hidden;
}

.related-posts__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.related-posts__card-body {
  padding: 16px 20px 20px;
}

.related-posts__date {
  font-family: var(--font-body);
  font-size: 0.8rem;
  color: var(--color-text-muted);
}

.related-posts__title {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 600;
  line-height: 1.3;
  margin: 8px 0 0;
}

.related-posts__title a {
  color: var(--color-text);
  text-decoration: none;
}

.related-posts__title a:hover {
  color: var(--color-accent);
}

@media (max-width: 768px) {
  .related-posts__grid {
    grid-template-columns: 1fr;
    gap: 20px;
  }
  .related-posts {
    padding: 40px 20px 60px;
  }
}

.newsletter-signup {
  padding: 80px 24px;
  text-align: center;
}

.newsletter-signup__inner {
  max-width: 560px;
  margin: 0 auto;
}

.newsletter-signup__heading {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 700;
  color: #ffffff;
  margin: 0 0 12px;
  letter-spacing: -0.01em;
}

.newsletter-signup__description {
  font-family: var(--font-body);
  font-size: 1.05rem;
  color: rgba(255,255,255,0.7);
  line-height: 1.6;
  margin: 0 0 28px;
}

.newsletter-signup__form {
  display: flex;
  gap: 8px;
  max-width: 420px;
  margin: 0 auto;
}

.newsletter-signup__input {
  flex: 1;
  padding: 14px 18px;
  font-family: var(--font-body);
  font-size: 1rem;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 8px;
  background: rgba(255,255,255,0.08);
  color: #ffffff;
  outline: none;
  transition: border-color 0.2s;
}

.newsletter-signup__input::placeholder {
  color: rgba(255,255,255,0.4);
}

.newsletter-signup__input:focus {
  border-color: var(--color-accent);
}

.newsletter-signup__button {
  padding: 14px 28px;
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  background: var(--color-accent);
  color: #ffffff;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 0.15s ease;
  white-space: nowrap;
}

.newsletter-signup__button:hover {
  transform: translateY(-1px);
}

@media (max-width: 640px) {
  .newsletter-signup {
    padding: 48px 20px;
  }
  .newsletter-signup__form {
    flex-direction: column;
  }
  .newsletter-signup__heading {
    font-size: 1.6rem;
  }
}

sharedCss:
:root {
  --color-bg: #ffffff;
  --color-surface: #f8f8fa;
  --color-accent: #e8613a;
  --color-text: #1a1a2e;
  --color-text-muted: #6b7280;
  --color-border: rgba(0,0,0,0.08);
  --font-heading: system-ui, -apple-system, sans-serif;
  --font-body: system-ui, -apple-system, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-body);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
}

a {
  color: var(--color-accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}
